insert into public.delivery_plan (uniq, part_number, tanggal, qty)
select d.uniq, d.part_number, (select b from bulan) + (i - 1), d.qty[i]
from data d, generate_series(1, array_length(d.qty, 1)) as i
on conflict (uniq, tanggal) do update
  set qty = excluded.qty, part_number = excluded.part_number;

